contracts/AirdropManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./Lib/Administrable.sol";
import "./Tools/Types.sol";

contract AirdropManager is Administrable {
    address _airdropDeployerERC20Address;
    address _airdropDeployerERC1155Address;
    address[] _airdrops;

    event AirdropAdded(address airdropAddress);
    event AirdropRemoved(address airdropAddress);
    event AirdropERC20Deployed(address airdropAddress);
    event AirdropERC1155Deployed(address airdropAddress);

    constructor(
        address[] memory initialAdmins,
        address airdropDeployerERC20Address,
        address airdropDeployerERC1155Address
    ) Administrable(initialAdmins) {
        _airdropDeployerERC20Address = airdropDeployerERC20Address;
        _airdropDeployerERC1155Address = airdropDeployerERC1155Address;
    }

    function claim(
        address airdropAddress,
        address user,
        uint256 amount,
        bytes32[] calldata proof
    ) public {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        airdrop.claim(user, amount, proof);
    }

    function hasClaimed(
        address airdropAddress,
        address user
    ) public view returns (bool) {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        return airdrop.hasClaimed(user);
    }

    function hasExpired(address airdropAddress) public view returns (bool) {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        return airdrop.hasExpired();
    }

    function isAllowed(
        address airdropAddress,
        address user
    ) public view returns (bool) {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        return airdrop.isAllowed(user);
    }

    function getExpirationDate(
        address airdropAddress
    ) public view returns (uint256) {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        return airdrop.getExpirationDate();
    }

    function getClaimAmount(
        address airdropAddress
    ) public view returns (uint256) {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        return airdrop.getClaimAmount();
    }

    function getAirdropInfo(
        address airdropAddress
    ) public view returns (AirdropInfo memory) {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        return airdrop.getAirdropInfo();
    }

    function getTotalAirdropAmount(
        address airdropAddress
    ) public view returns (uint256) {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        return airdrop.getTotalAirdropAmount();
    }

    function getAirdropAmountLeft(
        address airdropAddress
    ) public view returns (uint256) {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        return airdrop.getAirdropAmountLeft();
    }

    function getBalance(address airdropAddress) public view returns (uint256) {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        return airdrop.getBalance();
    }

    function getAirdrops() public view returns (address[] memory) {
        return _airdrops;
    }

    function deployAndAddAirdropERC20(
        string memory airdropName,
        address tokenAddress,
        uint256 totalAirdropAmount,
        uint256 claimAmount,
        uint256 expirationDate
    ) public returns(address) {
        IDeployerERC20 deployerERC20 = IDeployerERC20(_airdropDeployerERC20Address);
        address deployedAddress = deployerERC20.deployAndAddAirdrop(
            airdropName,
            tokenAddress,
            totalAirdropAmount,
            claimAmount,
            expirationDate
        );
        addAirdrop(deployedAddress);
        emit AirdropERC20Deployed(deployedAddress);
        return deployedAddress;
    }

    function deployAndAddAirdropERC1155(
        string memory airdropName,
        address tokenAddress,
        uint256 tokenId,
        uint256 totalAirdropAmount,
        uint256 claimAmount,
        uint256 expirationDate,
        uint256 mode
    ) public returns(address) {
        IDeployer1155 deployer1155 = IDeployer1155(_airdropDeployerERC1155Address);
        address deployedAddress = deployer1155.deployAndAddAirdrop(
            airdropName,
            tokenAddress,
            tokenId,
            totalAirdropAmount,
            claimAmount,
            expirationDate,
            mode
        );
        require(deployedAddress != address(0), "Error, wrong mode selected");
        addAirdrop(deployedAddress);
        emit AirdropERC1155Deployed(deployedAddress);
        return deployedAddress;
    }

    function addAirdrop(address newAirdropAddress) internal {
        bool exists = false;
        for (uint i = 0; i < _airdrops.length && !exists; i++) {
            exists = _airdrops[i] == newAirdropAddress;
        }
        require(!exists, "Airdrop already added");
        _airdrops.push(newAirdropAddress);
        emit AirdropAdded(newAirdropAddress);
    }

    function setRoot(address airdropAddress, bytes32 _root) public onlyAdmins {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        airdrop.setRoot(_root);
    }

    function removeAirdrop(address airdropAddress) public onlyAdmins {
        bool exists = false;
        for (uint i = 0; i < _airdrops.length && !exists; i++) {
            if (_airdrops[i] == airdropAddress) {
                exists = true;
                _airdrops[i] = _airdrops[_airdrops.length - 1];
                _airdrops.pop();
            }
        }

        if (exists) emit AirdropRemoved(airdropAddress);
    }

    function allowAddress(
        address airdropAddress,
        address user
    ) public onlyAdmins {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        airdrop.allowAddress(user);
    }

    function allowAddresses(
        address airdropAddress,
        address[] memory users
    ) public onlyAdmins {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        airdrop.allowAddresses(users);
    }

    function disallowAddress(
        address airdropAddress,
        address user
    ) public onlyAdmins {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        airdrop.disallowAddress(user);
    }

    function disallowAddresses(
        address airdropAddress,
        address[] memory users
    ) public onlyAdmins {
        IAirdrop airdrop = IAirdrop(airdropAddress);
        airdrop.disallowAddresses(users);
    }
}

contracts/ERC1155/CustomAirdrop1155.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "../Tools/Types.sol";

contract CustomAirdrop1155 is Ownable {
    event Claim(address recipient, uint256 amount);
    event AddressAllowed(address allowedAddress);
    event AddressDisallowed(address disallowedAddress);

    IERC1155 _tokenContract;
    uint256 _totalAirdropAmount;
    uint256 _airdropAmountLeft;
    uint256 _claimAmount;
    uint256 _expirationDate;
    uint256 _tokenId;
    string _airdropName;
    AirdropType _airdropType;

    mapping(address => bool) _allowedAddresses;
    mapping(address => bool) _addressesThatAlreadyClaimed;

    constructor(
        string memory airdropName,
        address initialOwner,
        address tokenAddress,
        uint256 tokenId,
        uint256 totalAirdropAmount,
        uint256 claimAmount,
        uint256 expirationDate,
        AirdropType airdropType
    ) Ownable(initialOwner) {
        _tokenContract = IERC1155(tokenAddress);
        _airdropName = airdropName;
        _tokenId = tokenId;
        _totalAirdropAmount = totalAirdropAmount;
        _airdropAmountLeft = totalAirdropAmount;
        _claimAmount = claimAmount;
        _expirationDate = expirationDate;
        _airdropType = airdropType;
    }

    function claim(address user, uint256 amount, bytes32[] calldata proof) public onlyOwner {
        require(isAllowed(user), "Address not allowed to claim this airdrop");
        require(!hasExpired(), "Airdrop already expired.");
        require(!hasClaimed(user), "Address already claimed this airdrop.");
        require(!hasBeenTotallyClaimed(), "Airdrop has been totally claimed already.");
        require(hasBalanceToClaim(), "Airdrop contract has insufficient token balance.");

        _tokenContract.safeTransferFrom(address(this), user, _tokenId, _claimAmount, '');
        _airdropAmountLeft -= _claimAmount;
        _addressesThatAlreadyClaimed[user] = true;

        emit Claim(user, _claimAmount);
    }

    function getAirdropInfo() public view returns(AirdropInfo memory) {
        return AirdropInfo(_airdropName, address(this), _totalAirdropAmount, _airdropAmountLeft, _claimAmount, _expirationDate, _airdropType, '');
    }

    function hasBalanceToClaim() public view returns(bool) {
        return _tokenContract.balanceOf(address(this), _tokenId) >= _claimAmount;
    }

    function hasBeenTotallyClaimed() public view returns(bool) {
        return _airdropAmountLeft < _claimAmount;
    }

    function hasClaimed(address _address) public view returns(bool) {
        return _addressesThatAlreadyClaimed[_address];
    }

    function hasExpired() public view returns(bool) {
        return _expirationDate < block.timestamp;
    }

    function allowAddress(address _address) public onlyOwner {
        _allowedAddresses[_address] = true;
        emit AddressAllowed(_address);
    }

    function allowAddresses(address[] memory addresses) public onlyOwner {
        for (uint i; i < addresses.length; i++) {
            _allowedAddresses[addresses[i]] = true;
            emit AddressAllowed(addresses[i]);
        }
    }

    function disallowAddresses(address[] memory addresses) public onlyOwner {
        for (uint i; i < addresses.length; i++) {
            _allowedAddresses[addresses[i]] = false;
            emit AddressDisallowed(addresses[i]);
        }
    }

    function disallowAddress(address _address) public onlyOwner {
        _allowedAddresses[_address] = false;
        emit AddressDisallowed(_address);
    }

    function isAllowed(address _address) public view returns(bool) {
        return _allowedAddresses[_address];
    }

    function getExpirationDate() public view returns(uint256) {
        return _expirationDate;
    }

    function getClaimAmount() public view returns(uint256) {
        return _claimAmount;
    }

    function getTotalAirdropAmount() public view returns(uint256) {
        return _totalAirdropAmount;
    }

    function getAirdropAmountLeft() public view returns(uint256) {
        return _airdropAmountLeft;
    }

    function getBalance() public view returns(uint256) {
        return _tokenContract.balanceOf(address(this), _tokenId);
    }

    function onERC1155Received(address operator, address from, uint256 id, uint256 value, bytes memory data) external pure returns (bytes4) {
        return bytes4(keccak256("onERC1155Received(address,address,uint256,uint256,bytes)"));
    }

    function getUri() public view returns (string memory) {
        //NOT IMPLEMENTED YET
        return 'not implemented';
    }
}

